 static int count;
 static Bounds BoundsOf(GameObject g){var r=g.GetComponentsInChildren<Renderer>();var b=r[0].bounds;foreach(var x in r)b.Encapsulate(x.bounds);return b;}
 // 기존 충돌과 엄폐 판정을 보존하고, 새 가구 외형을 그 공간에 맞춘다.
 static GameObject Prop(string path,Transform parent,Vector3 bottom,Vector3 size,float yaw=0,bool uniform=false){var asset=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(!asset)throw new Exception("Missing "+path);var g=(GameObject)PrefabUtility.InstantiatePrefab(asset,parent);g.transform.rotation=Quaternion.Euler(0,yaw,0);var b=BoundsOf(g);var factor=new Vector3(size.x/b.size.x,size.y/b.size.y,size.z/b.size.z);if(uniform)factor=Vector3.one*Mathf.Min(factor.x,factor.y,factor.z);g.transform.localScale=Vector3.Scale(g.transform.localScale,factor);b=BoundsOf(g);g.transform.position+=bottom-new Vector3(b.center.x,b.min.y,b.center.z);foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);count++;return g;}
 public static void Apply(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit mode required");var scene=SceneManager.GetSceneByPath(BankPrologueBuilder.ScenePath);if(!scene.isLoaded)scene=EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath,OpenSceneMode.Additive);var oldActive=SceneManager.GetActiveScene();SceneManager.SetActiveScene(scene);if(!EditorSceneManager.SaveScene(scene,"Logs/Bank-before-synty-furnishing-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true))throw new Exception("Backup failed");var w=scene.GetRootGameObjects().Single(g=>g.name=="BANK / Saved Architecture").transform;var d=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<BankPrologue>(true)).Single();var old=w.Find("Synty bank furnishing");if(old)throw new Exception("Already furnished; preserve subsequent edits");var root=new GameObject("Synty bank furnishing").transform;root.SetParent(w,false);root.position=Vector3.zero;count=0;
 var hidden=new HashSet<string>{"Cover desk","Desk top","Computer monitor","Paperwork","Counter bronze fascia","Monitor stand","Screen display","Terminal text line","Keyboard","Document tray","Pen stand","Counter pen","Waiting sofa","Sofa back","Upholstered waiting seat","Waiting seat back cushion","Cabinet body","Drawer face","Drawer handle","Safe deposit case","Safe box door","Safe box latch"};foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true))if(hidden.Contains(r.name))r.enabled=false;
 foreach(float z in new[]{-13f,-25f,-36f,-46f})foreach(float x in new[]{-6f,5f}){Prop(P+"SM_Prop_TellerDesk_01.prefab",root,new Vector3(x,0,z),new Vector3(3.2f,1.41f,1.5f));Prop(P+"SM_Prop_Computer_Screen_01.prefab",root,new Vector3(x,1.42f,z+.15f),new Vector3(.7f,.55f,.22f));Prop(P+"SM_Prop_Computer_Keyboard_01.prefab",root,new Vector3(x,1.42f,z-.37f),new Vector3(.58f,.05f,.19f));Prop(P+"SM_Prop_Folder_01.prefab",root,new Vector3(x+.9f,1.42f,z),new Vector3(.45f,.08f,.35f));Prop(P+"SM_Prop_DeskLight_01.prefab",root,new Vector3(x-1,1.42f,z+.12f),new Vector3(.35f,.5f,.3f),0,true);}
 foreach(float x in new[]{-13f,-8f,-3f,2f,7f})Prop(P+"SM_Prop_Couch_01.prefab",root,new Vector3(x,0,-47.5f),new Vector3(3,1.4f,1.05f));
 foreach(float z in new[]{-24f,-35f})Prop(P+"SM_Prop_Drawers_01.prefab",root,new Vector3(17.2f,0,z),new Vector3(.65f,2.1f,2.2f),90);
 foreach(float x in new[]{-7.8f,7.8f})Prop(P+"SM_Prop_SafeDepositBoxes_01.prefab",root,new Vector3(x,.1f,15.65f),new Vector3(3.6f,3.2f,.3f));
 // 금고 가동부와 현금 작업대는 보존하고 벽면 수납만 교체한다.
 Prop(P+"SM_Prop_WaterCooler_01.prefab",root,new Vector3(-16.8f,0,-44),new Vector3(.7f,1.5f,.7f),0,true);Prop(P+"SM_Prop_Bin_01.prefab",root,new Vector3(-15.6f,0,-44),new Vector3(.5f,.8f,.5f),0,true);
 foreach(float z in new[]{-20f,-32f})Prop(P+"SM_Prop_Plant_02.prefab",root,new Vector3(16.7f,0,z),new Vector3(.9f,1.7f,.9f),0,true);
 // 은행 맞은편 상가와 보도. 주행 차선 및 경찰 접근 구간은 비운다.
 var ground=GameObject.CreatePrimitive(PrimitiveType.Cube);ground.name="District foundation";ground.transform.SetParent(root,false);ground.transform.position=new Vector3(110,-.55f,-65);ground.transform.localScale=new Vector3(450,.2f,260);ground.GetComponent<Renderer>().sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Art+"Limestone.mat");UnityEngine.Object.DestroyImmediate(ground.GetComponent<Collider>());
 foreach(int i in Enumerable.Range(0,5)){Prop(C+"Buildings/SM_Bld_Shop_0"+(i%3+1)+".prefab",root,new Vector3(-35+i*16,0,-97),new Vector3(15,18,20),0,true);}
 foreach(int i in Enumerable.Range(0,7))Prop(C+"Buildings/SM_Bld_Apartment_0"+(i%3+1)+".prefab",root,new Vector3(-45+i*22,0,-127),new Vector3(21,40,24),0,true);
 int building=0;foreach(var t in w.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="SM_Bld_Apartment_01(Clone)"&&t.position.x>=40&&t.position.z<0).ToArray()){var b=BoundsOf(t.gameObject);Prop(C+"Buildings/SM_Bld_Apartment_0"+(building++%3+1)+".prefab",root,new Vector3(b.center.x,b.min.y,b.center.z),new Vector3(23,Mathf.Clamp(b.size.y,22,38),23),t.eulerAngles.y,true);foreach(var r in t.GetComponentsInChildren<Renderer>())r.enabled=false;}
 foreach(float x in new[]{-18f,-2f,34f,82f,130f,178f,226f}){Prop(C+"Props/SM_Prop_ParkBench_01.prefab",root,new Vector3(x,0,-78),new Vector3(2.2f,1.1f,.8f),0,true);Prop(C+"Props/SM_Prop_Trashbin_02.prefab",root,new Vector3(x+2,0,-78),new Vector3(.65f,1,.65f),0,true);Prop(C+"Props/SM_Prop_PotPlant_02.prefab",root,new Vector3(x-3,0,-79),new Vector3(1.2f,2,1.2f),0,true);}
 Prop(C+"Props/SM_Prop_BusStop_01.prefab",root,new Vector3(-12,0,-79),new Vector3(6,3.2f,2),0,true);Prop(C+"Props/SM_Prop_Hydrant_01.prefab",root,new Vector3(3,0,-77),new Vector3(.6f,.85f,.6f),0,true);
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Capture(new Vector3(-13,2.1f,-43),new Vector3(4,1.5f,-36),"Bank-Synty-interior");Capture(new Vector3(13,2,-54),new Vector3(9,4,-98),"Bank-Synty-exterior");File.WriteAllText("Logs/Bank-Synty-apply.txt","PASS saved "+count+" Synty furnishings and district props; original vault, cash interaction, collision and escape route retained");if(oldActive.isLoaded)SceneManager.SetActiveScene(oldActive);}
 public static void Refine(){var scene=SceneManager.GetSceneByPath(BankPrologueBuilder.ScenePath);if(EditorApplication.isPlaying||!scene.isLoaded)throw new Exception("Open bank edit scene");EditorSceneManager.SaveScene(scene,"Logs/Bank-before-synty-core-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var w=scene.GetRootGameObjects().Single(g=>g.name=="BANK / Saved Architecture").transform;var parent=w.Find("Synty bank furnishing");if(parent.Find("Core hall furnishings"))throw new Exception("Already refined");var root=new GameObject("Core hall furnishings").transform;root.SetParent(parent,false);root.position=Vector3.zero;
 foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true))if(new[]{"Counter","Countertop","Teller divider","Monitor","Waiting bench","Bench back"}.Contains(r.name)||(r.transform.position.z>-8&&(r.name=="Plant"||r.name=="Planter")))r.enabled=false;
 foreach(float x in new[]{-6f,6f}){Prop(P+"SM_Prop_TellerDesk_02.prefab",root,new Vector3(x,0,2),new Vector3(4.2f,1.41f,2.2f));for(int k=-1;k<=1;k++){Prop(P+"SM_Prop_Computer_Screen_01.prefab",root,new Vector3(x+k*1.3f,1.42f,2.15f),new Vector3(.6f,.45f,.22f));Prop(P+"SM_Prop_Computer_Keyboard_01.prefab",root,new Vector3(x+k*1.3f,1.42f,1.65f),new Vector3(.5f,.04f,.2f));}Prop(P+"SM_Prop_Couch_02.prefab",root,new Vector3(x,0,-4.8f),new Vector3(3,1.35f,1));}
 foreach(float x in new[]{-8.5f,8.5f})foreach(float z in new[]{-5f,1f,7f})Prop(P+"SM_Prop_Plant_03.prefab",root,new Vector3(x,0,z),new Vector3(.8f,1.5f,.8f),0,true);
 foreach(var r in w.GetComponentsInChildren<MeshRenderer>(true))if((r.name=="Planter"||r.name=="Trimmed hedge")&&r.transform.position.z<-50&&r.transform.position.z>-55)r.enabled=false;
 foreach(float x in new[]{-17f,-12f,-7f,-2f,3f,8f})Prop(C+"Props/SM_Prop_Planter_01.prefab",root,new Vector3(x,0,-53),new Vector3(2,1.4f,1.2f),0,true);
 EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Preview();Capture(new Vector3(0,2,-3),new Vector3(-6,1.5f,2),"Bank-Synty-core");}
 public static void Preview(){for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Save scene edits before preview");EditorSceneManager.OpenScene(BankPrologueBuilder.ScenePath);Capture(new Vector3(-1,2.1f,-43),new Vector3(5,1.6f,-46),"Bank-Synty-interior");Capture(new Vector3(13,2,-54),new Vector3(9,4,-98),"Bank-Synty-exterior");}
 static void Capture(Vector3 from,Vector3 at,string name){var g=new GameObject("Bank design preview");var c=g.AddComponent<Camera>();var rt=new RenderTexture(1280,720,24);var old=RenderTexture.active;try{c.transform.position=from;c.transform.LookAt(at);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes("Logs/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}
}}
